use anyhow::{Context, Result};
use clap::Parser;
use regex::Regex;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

mod patterns;
mod randomness;
mod secretsignore;

use patterns::PATTERNS;
use randomness::has_sufficient_randomness;
use secretsignore::{parse_secretsignore, SecretsIgnore};

#[derive(Parser, Debug)]
#[command(
    name = "ripsecrets",
    version = "0.1.11",
    about = "ripsecrets searches files and directories recursively for secret API keys.\nIt's primarily designed to be used as a pre-commit to prevent committing\nsecrets into version control.",
    long_about = None
)]
struct Args {
    /// Source files. Can be files or directories. Defaults to '.'
    #[arg(value_name = "Source files")]
    sources: Vec<PathBuf>,

    /// Install `ripsecrets` as a pre-commit hook automatically in git directory provided
    #[arg(long)]
    install_pre_commit: bool,

    /// If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit
    #[arg(long)]
    strict_ignore: bool,

    /// Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line
    #[arg(long)]
    only_matching: bool,

    /// Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret
    #[arg(long, value_name = "ADDITIONAL_PATTERNS")]
    additional_pattern: Vec<String>,
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.install_pre_commit {
        // TODO: Implement pre-commit hook installation
        println!("Pre-commit hook installation not yet implemented");
        return Ok(());
    }

    // Default to current directory if no sources specified
    let sources = if args.sources.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.sources
    };

    // Compile additional patterns
    let mut additional_regexes = Vec::new();
    for pattern in &args.additional_pattern {
        additional_regexes.push(Regex::new(pattern)?);
    }

    // Load .secretsignore file
    let secrets_ignore = parse_secretsignore(Path::new(".secretsignore"))?;

    let mut found_secrets = false;

    for source in &sources {
        if source.is_dir() {
            found_secrets |= scan_directory(
                source,
                &secrets_ignore,
                &additional_regexes,
                args.strict_ignore,
                args.only_matching,
            )?;
        } else {
            found_secrets |= scan_file(
                source,
                &secrets_ignore,
                &additional_regexes,
                args.strict_ignore,
                args.only_matching,
            )?;
        }
    }

    if found_secrets {
        std::process::exit(1);
    }

    Ok(())
}

fn scan_directory(
    dir: &Path,
    secrets_ignore: &SecretsIgnore,
    additional_regexes: &[Regex],
    strict_ignore: bool,
    only_matching: bool,
) -> Result<bool> {
    let mut found_secrets = false;

    for entry in WalkDir::new(dir)
        .into_iter()
        .filter_map(|e| e.ok())
    {
        let path = entry.path();

        // Skip directories
        if path.is_dir() {
            continue;
        }

        // Check if file should be ignored
        if secrets_ignore.should_ignore_file(path) {
            continue;
        }

        found_secrets |= scan_file(path, secrets_ignore, additional_regexes, strict_ignore, only_matching)?;
    }

    Ok(found_secrets)
}

fn scan_file(
    path: &Path,
    secrets_ignore: &SecretsIgnore,
    additional_regexes: &[Regex],
    _strict_ignore: bool,
    only_matching: bool,
) -> Result<bool> {
    // Try to read file as text
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return Ok(false), // Skip binary files
    };

    let mut found_secrets = false;

    for (line_num, line) in content.lines().enumerate() {
        let line_num = line_num + 1;

        // Check against default patterns
        for (pattern_name, pattern_regex) in PATTERNS {
            if let Some(captures) = pattern_regex.captures(line) {
                // Check if we have a capture group, if so use it for randomness check
                let secret = if pattern_regex.captures_len() > 1 {
                    captures.get(1).map(|m| m.as_str())
                } else {
                    captures.get(0).map(|m| m.as_str())
                };

                if let Some(secret_str) = secret {
                    // Check if secret is in the ignore list
                    if secrets_ignore.ignored_secrets.contains(secret_str) {
                        continue;
                    }

                    // Check randomness (skip for private keys)
                    if pattern_name.contains("PRIVATE") {
                        // Private keys are always considered secrets
                        found_secrets = true;
                        if only_matching {
                            println!("{}:{}:{}", path.display(), line_num, secret_str);
                        } else {
                            println!("{}:{}:{}", path.display(), line_num, line);
                        }
                    } else if has_sufficient_randomness(secret_str) {
                        found_secrets = true;
                        if only_matching {
                            println!("{}:{}:{}", path.display(), line_num, secret_str);
                        } else {
                            println!("{}:{}:{}", path.display(), line_num, line);
                        }
                    }
                }
            }
        }

        // Check against additional patterns
        for additional_regex in additional_regexes {
            if let Some(captures) = additional_regex.captures(line) {
                let secret = if additional_regex.captures_len() > 1 {
                    captures.get(1).map(|m| m.as_str())
                } else {
                    captures.get(0).map(|m| m.as_str())
                };

                if let Some(secret_str) = secret {
                    // Check if secret is in the ignore list
                    if secrets_ignore.ignored_secrets.contains(secret_str) {
                        continue;
                    }

                    // Check randomness
                    if has_sufficient_randomness(secret_str) {
                        found_secrets = true;
                        if only_matching {
                            println!("{}:{}:{}", path.display(), line_num, secret_str);
                        } else {
                            println!("{}:{}:{}", path.display(), line_num, line);
                        }
                    }
                }
            }
        }
    }

    Ok(found_secrets)
}
