use anyhow::Result;
use std::collections::HashSet;
use std::fs;
use std::path::Path;

pub struct SecretsIgnore {
    pub ignored_files: Vec<String>,
    pub ignored_secrets: HashSet<String>,
}

impl SecretsIgnore {
    pub fn new() -> Self {
        SecretsIgnore {
            ignored_files: Vec::new(),
            ignored_secrets: HashSet::new(),
        }
    }

    pub fn should_ignore_file(&self, path: &Path) -> bool {
        let path_str = path.to_string_lossy();

        for pattern in &self.ignored_files {
            // Simple glob pattern matching
            if matches_pattern(&path_str, pattern) {
                return true;
            }
        }
        false
    }
}

fn matches_pattern(path: &str, pattern: &str) -> bool {
    // Simple gitignore-like matching
    // If pattern contains /, it's a path pattern
    // Otherwise, it matches filename

    if pattern.contains('/') {
        // Path pattern - match against full path
        path.contains(pattern) || path.ends_with(pattern)
    } else {
        // Filename pattern - match against filename or anywhere in path
        path.contains(&format!("/{}", pattern)) || path.ends_with(pattern) || path == pattern
    }
}

pub fn parse_secretsignore(path: &Path) -> Result<SecretsIgnore> {
    let mut secrets_ignore = SecretsIgnore::new();

    if !path.exists() {
        return Ok(secrets_ignore);
    }

    let content = fs::read_to_string(path)?;
    let mut in_secrets_section = false;

    for line in content.lines() {
        let line = line.trim();

        // Skip empty lines and comments
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        if line == "[secrets]" {
            in_secrets_section = true;
            continue;
        }

        if in_secrets_section {
            secrets_ignore.ignored_secrets.insert(line.to_string());
        } else {
            secrets_ignore.ignored_files.push(line.to_string());
        }
    }

    Ok(secrets_ignore)
}
