pub fn get_compiled_patterns() -> Vec<(String, Regex)> {
    let patterns = vec![
        // AWS credentials
        ("AWS_SECRET", r"(?:aws_secret_access_key|aws_secret_key|secret_access_key)\s*[=:]\s*([A-Za-z0-9/+=]{40})"),
        ("AWS_KEY_ID", r"(?:api_key|api_secret|access_key|api_token)\s*[=:]\s*(AKIA[0-9A-Z]{16})"),

        // Firebase
        ("FIREBASE", r"(?:firebase_api_key|firebase_key)\s*[=:]\s*(AIzaSy[0-9A-Za-z_-]{33})"),

        // Slack
        ("SLACK", r"(?:slack_token|slack_webhook|xoxp|xoxb)\s*[=:]*\s*(xo[baprs]-[0-9]{10,13}-[0-9]{10,13}-[0-9A-Za-z]{32})"),

        // Stripe
        ("STRIPE", r"(?:stripe_api|stripe_key|stripe_secret|sk_live)\s*[=:]*\s*(sk_live_[0-9A-Za-z]{24})"),

        // GitHub tokens
        ("GITHUB_TOKEN", r"(?:github_token|gh_token|ghp_token|ghp_)\s*[=:]*\s*(ghp_[0-9A-Za-z]{36})"),

        // Twilio
        ("TWILIO", r"(?:twilio_account|twilio_key|AC[0-9a-f]{32})\s*[=:]*\s*(AC[0-9a-f]{32})"),

        // NPM tokens
        ("NPM_TOKEN", r"(?:npm_token|npmrc|npm_)\s*[=:]*\s*(npm_[0-9A-Za-z]{36})"),

        // Private keys
        ("PRIVATE_KEY_RSA", r"-----BEGIN RSA PRIVATE KEY-----"),
        ("PRIVATE_KEY_DSA", r"-----BEGIN DSA PRIVATE KEY-----"),
        ("PRIVATE_KEY_EC", r"-----BEGIN EC PRIVATE KEY-----"),
        ("PRIVATE_KEY_OPENSSH", r"-----BEGIN OPENSSH PRIVATE KEY-----"),
        ("PRIVATE_KEY_GENERIC", r"-----BEGIN PRIVATE KEY-----"),
        ("PRIVATE_KEY_ENCRYPTED", r"-----BEGIN ENCRYPTED PRIVATE KEY-----"),
        ("PRIVATE_KEY_PGP", r"-----BEGIN PGP PRIVATE KEY BLOCK-----"),

        // JWT
        ("JWT", r"(eyJ[0-9A-Za-z_-]{20,}\.eyJ[0-9A-Za-z_-]{20,}\.[0-9A-Za-z_-]{20,})"),
    ];

    patterns.iter()
        .map(|(name, pattern)| {
            (name.to_string(), Regex::new(pattern).expect("Invalid regex pattern"))
        })
        .collect()
}
