    pub fn find_with_capture(&self, text: &str) -> Option<(&str, Option<&str>)> {
        self.find_in_text(text)
    }

    fn find_in_text(&self, text: &str) -> Option<(&str, Option<&str>)> {
        let p = &self.pattern;

        // Handle different pattern types
        if p.contains("-----BEGIN") {
            // Private key patterns - literal substring match
            if let Some(pos) = text.find(p) {
                let end = text[pos..].find('\n').map(|x| pos + x).unwrap_or(text.len());
                return Some((&text[pos..end], None));
            }
        }

        if p.contains("eyJ") {
            // JWT pattern
            return self.match_jwt(text);
        }

        if p.contains("(?:") {
            // Named group pattern
            return self.match_named_group_pattern(text);
        }

        None
    }

    fn match_jwt(&self, text: &str) -> Option<(&str, Option<&str>)> {
        // Match JWT pattern: eyJ...eyJ...base64chars
        let mut search_pos = 0;
        while let Some(eyj_pos) = text[search_pos..].find("eyJ") {
            let pos = search_pos + eyj_pos;
            let rest = &text[pos..];

            // Find the first part until a dot
            let mut i = 0;
            while i < rest.len() && rest.chars().nth(i) != Some('.') {
                i += 1;
            }

            if i + 1 < rest.len() && rest.chars().nth(i) == Some('.') {
                // Check second part starts with eyJ
                let second_part = &rest[i+1..];
                if second_part.starts_with("eyJ") {
                    // Find until next dot
                    let mut j = 0;
                    while j < second_part.len() && second_part.chars().nth(j) != Some('.') {
                        j += 1;
                    }

                    if j + 1 < second_part.len() && second_part.chars().nth(j) == Some('.') {
                        // Extract the third part (signature)
                        let third_part = &second_part[j+1..];
                        let mut k = 0;
                        while k < third_part.len() {
                            let ch = third_part.chars().nth(k).unwrap();
                            if !is_base64_char(ch) && !is_url_safe_char(ch) {
                                break;
                            }
                            k += 1;
                        }

                        if k > 20 {
                            let matched = &rest[..i + 1 + j + 1 + k];
                            return Some((matched, Some(matched)));
                        }
                    }
                }
            }
            search_pos = pos + 3;
        }
        None
    }

    fn match_named_group_pattern(&self, text: &str) -> Option<(&str, Option<&str>)> {
        let p = &self.pattern;

        // Parse pattern like: (?:aws_secret_access_key|aws_secret_key|secret_access_key)\s*[=:]\s*([A-Za-z0-9/+=]{40})
        // Extract variable names and capture pattern
        if let Some(names_start) = p.find("(?:") {
            if let Some(names_end) = p.find(")") {
                let names_part = &p[names_start + 3..names_end];
                let names: Vec<&str> = names_part.split('|').collect();

                let after_names = &p[names_end + 1..];

                // Extract the separator and capture pattern
                let sep_and_capture = after_names;

                // Try to match any of the variable names
                for name in names {
                    // Build search pattern
                    let search_pat = format!("{}{}", name, "\\s*[=:]");

                    // Find occurrences of name followed by = or :
                    let mut search_pos = 0;
                    while let Some(name_pos) = text[search_pos..].find(name) {
                        let pos = search_pos + name_pos;
                        let after_name = &text[pos + name.len()..];

                        // Skip whitespace and find = or :
                        let mut eq_pos = 0;
                        while eq_pos < after_name.len() && after_name.chars().nth(eq_pos).unwrap().is_whitespace() {
                            eq_pos += 1;
                        }

                        if eq_pos < after_name.len() {
                            let ch = after_name.chars().nth(eq_pos).unwrap();
                            if ch == '=' || ch == ':' {
                                // Found the pattern, now extract the value
                                let value_start = eq_pos + 1;
                                let value_part = &after_name[value_start..];

                                // Skip leading whitespace
                                let mut val_start = 0;
                                while val_start < value_part.len() && value_part.chars().nth(val_start).unwrap().is_whitespace() {
                                    val_start += 1;
                                }

                                // Extract value based on capture pattern
                                let value = self.extract_capture_value(&value_part[val_start..]);
                                if let Some((matched_len, captured)) = value {
                                    let full_match_len = pos + name.len() + eq_pos + 1 + val_start + matched_len;
