use std::collections::HashSet;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

mod patterns;
mod randomness;
mod secretsignore;
mod regex;

use patterns::PATTERNS;
use randomness::has_sufficient_randomness;
use secretsignore::{parse_secretsignore, SecretsIgnore};
use regex::SimpleRegex;

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut sources = Vec::new();
    let mut additional_patterns = Vec::new();
    let mut only_matching = false;
    let mut strict_ignore = false;
    let mut install_pre_commit = false;
    let mut show_help = false;
    let mut show_version = false;

    // Parse arguments
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                show_help = true;
            }
            "-V" | "--version" => {
                show_version = true;
            }
            "--only-matching" => {
                only_matching = true;
            }
            "--strict-ignore" => {
                strict_ignore = true;
            }
            "--install-pre-commit" => {
                install_pre_commit = true;
            }
            "--additional-pattern" => {
                i += 1;
                if i < args.len() {
                    additional_patterns.push(args[i].clone());
                }
            }
            arg if arg.starts_with('-') => {
                eprintln!("Unknown argument: {}", arg);
                std::process::exit(1);
            }
            _ => {
                sources.push(PathBuf::from(&args[i]));
            }
        }
        i += 1;
    }

    if show_help {
        print_help();
        return;
    }

    if show_version {
        println!("ripsecrets 0.1.11");
        return;
    }

    if install_pre_commit {
        println!("Pre-commit hook installation not yet implemented");
        return;
    }

    // Default to current directory if no sources specified
    if sources.is_empty() {
        sources.push(PathBuf::from("."));
    }

    // Compile additional patterns
    let additional_regexes: Vec<SimpleRegex> = additional_patterns
        .iter()
        .map(|p| SimpleRegex::new(p))
        .collect();

    // Load .secretsignore file
    let secrets_ignore = match parse_secretsignore(Path::new(".secretsignore")) {
        Ok(si) => si,
        Err(e) => {
            eprintln!("Error reading .secretsignore: {}", e);
            std::process::exit(1);
        }
    };

    let mut found_secrets = false;

    for source in &sources {
        if source.is_dir() {
            if let Ok(has_secrets) = scan_directory(
                source,
                &secrets_ignore,
                &additional_regexes,
                strict_ignore,
                only_matching,
            ) {
                found_secrets |= has_secrets;
            }
        } else {
            if let Ok(has_secrets) = scan_file(
                source,
                &secrets_ignore,
                &additional_regexes,
                strict_ignore,
                only_matching,
            ) {
                found_secrets |= has_secrets;
            }
        }
    }

    if found_secrets {
        std::process::exit(1);
    }
}

fn print_help() {
    println!("ripsecrets searches files and directories recursively for secret API keys.");
    println!("It's primarily designed to be used as a pre-commit to prevent committing");
    println!("secrets into version control.");
    println!();
    println!("Usage: executable [OPTIONS] [Source files]...");
    println!();
    println!("Arguments:");
    println!("  [Source files]...");
    println!("          Source files. Can be files or directories. Defaults to '.'");
    println!();
    println!("Options:");
    println!("      --install-pre-commit");
    println!("          Install `ripsecrets` as a pre-commit hook automatically in git directory provided");
    println!();
    println!("      --strict-ignore");
    println!("          If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit");
    println!();
    println!("      --only-matching");
    println!("          Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line");
    println!();
    println!("      --additional-pattern <ADDITIONAL_PATTERNS>");
    println!("          Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret");
    println!();
    println!("  -h, --help");
    println!("          Print help (see a summary with '-h')");
    println!();
    println!("  -V, --version");
    println!("          Print version");
}

fn scan_directory(
    dir: &Path,
    secrets_ignore: &SecretsIgnore,
    additional_regexes: &[SimpleRegex],
    _strict_ignore: bool,
    only_matching: bool,
) -> std::io::Result<bool> {
    let mut found_secrets = false;

    fn walk(
        dir: &Path,
        secrets_ignore: &SecretsIgnore,
        additional_regexes: &[SimpleRegex],
        only_matching: bool,
        found_secrets: &mut bool,
    ) -> std::io::Result<()> {
        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();

            // Check if file should be ignored
            if secrets_ignore.should_ignore_file(&path) {
                continue;
            }

            if path.is_dir() {
                walk(&path, secrets_ignore, additional_regexes, only_matching, found_secrets)?;
            } else {
                if let Ok(has_secrets) = scan_file(&path, secrets_ignore, additional_regexes, false, only_matching) {
                    *found_secrets |= has_secrets;
                }
            }
        }
        Ok(())
    }

    walk(dir, secrets_ignore, additional_regexes, only_matching, &mut found_secrets)?;
    Ok(found_secrets)
}

fn scan_file(
    path: &Path,
    secrets_ignore: &SecretsIgnore,
    additional_regexes: &[SimpleRegex],
    _strict_ignore: bool,
    only_matching: bool,
) -> std::io::Result<bool> {
    // Try to read file as text
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return Ok(false), // Skip binary files
    };

    let mut found_secrets = false;

    for (line_num, line) in content.lines().enumerate() {
        let line_num = line_num + 1;

        // Check against default patterns
        for (pattern_name, pattern_str) in PATTERNS {
            let regex = SimpleRegex::new(pattern_str);
            if let Some((_matched_text, capture)) = regex.find_with_capture(line) {
                let secret = capture.unwrap_or(line);

                // Check if secret is in the ignore list
                if secrets_ignore.ignored_secrets.contains(secret) {
                    continue;
                }

                // Check randomness (skip for private keys)
                if pattern_name.contains("PRIVATE") {
                    // Private keys are always considered secrets
                    found_secrets = true;
                    if only_matching {
                        println!("{}:{}:{}", path.display(), line_num, secret);
                    } else {
                        println!("{}:{}:{}", path.display(), line_num, line);
                    }
                } else if has_sufficient_randomness(secret) {
                    found_secrets = true;
                    if only_matching {
                        println!("{}:{}:{}", path.display(), line_num, secret);
                    } else {
                        println!("{}:{}:{}", path.display(), line_num, line);
                    }
                }
            }
        }

        // Check against additional patterns
        for pattern in additional_regexes {
            if let Some((_matched_text, capture)) = pattern.find_with_capture(line) {
                let secret = capture.unwrap_or(line);

                // Check if secret is in the ignore list
                if secrets_ignore.ignored_secrets.contains(secret) {
                    continue;
                }

                // Check randomness
                if has_sufficient_randomness(secret) {
                    found_secrets = true;
                    if only_matching {
                        println!("{}:{}:{}", path.display(), line_num, secret);
                    } else {
                        println!("{}:{}:{}", path.display(), line_num, line);
                    }
                }
            }
        }
    }

    Ok(found_secrets)
}
