use std::collections::HashMap;

pub fn has_sufficient_randomness(s: &str) -> bool {
    if s.len() < 20 {
        return false;
    }

    // Count unique characters and character types
    let mut char_freq: HashMap<char, usize> = HashMap::new();

    for ch in s.chars() {
        *char_freq.entry(ch).or_insert(0) += 1;
    }

    // Calculate entropy: unique characters / length
    let unique_chars = char_freq.len() as f64;
    let length = s.len() as f64;
    let entropy = unique_chars / length;

    // Check if any single character appears too frequently (low entropy)
    let max_freq = *char_freq.values().max().unwrap_or(&0) as f64;
    let freq_ratio = max_freq / length;

    // Heuristics for randomness:
    // 1. At least 20 characters
    // 2. Entropy > 0.5 (more than 50% unique characters)
    // 3. No single character dominates (max frequency < 40%)

    entropy > 0.5 && freq_ratio < 0.4
}
EOF

