    fn find_in_text<'a>(&self, text: &'a str) -> Option<(&'a str, Option<&'a str>)> {
        let p = &self.pattern;

        // Handle different pattern types
        if p.contains("-----BEGIN") {
            // Private key patterns - literal substring match
            if let Some(pos) = text.find(p) {
                if let Some(newline_pos) = text[pos..].find('\n') {
                    let end = pos + newline_pos;
                    return Some((&text[pos..end], None));
                } else {
                    return Some((&text[pos..], None));
                }
            }
