                            let matched = &rest[..i + 1 + j + 1 + k];
                            return Some((matched, Some(matched)));
                        }
                    }
                }
            }
            search_pos = pos + 3;
        }
        None
    }

    fn match_named_group_pattern<'a>(&self, text: &'a str) -> Option<(&'a str, Option<&'a str>)> {
        let p = &self.pattern;

        // Parse pattern like: (?:aws_secret_access_key|aws_secret_key|secret_access_key)\s*[=:]\s*([A-Za-z0-9/+=]{40})
        // Extract variable names and capture pattern
        if let Some(names_start) = p.find("(?:") {
            if let Some(names_end) = p[names_start..].find(")") {
                let names_end_abs = names_start + names_end;
                let names_part = &p[names_start + 3..names_end_abs];
                let names: Vec<&str> = names_part.split('|').collect();

                // Try to match any of the variable names
                for name in &names {
                    // Find occurrences of name
                    let mut search_pos = 0;
                    while let Some(name_pos) = text[search_pos..].find(name) {
                        let pos = search_pos + name_pos;

                        // Check if this is a word boundary (not preceded by alphanumeric)
                        let is_start = pos == 0 || !text.chars().nth(pos - 1).unwrap().is_alphanumeric();
                        let is_end = pos + name.len() >= text.len() || !text.chars().nth(pos + name.len()).unwrap().is_alphanumeric();

                        if !is_start || !is_end {
                            search_pos = pos + 1;
                            continue;
                        }

                        let after_name = &text[pos + name.len()..];

                        // Skip whitespace and find = or :
                        let mut eq_pos = 0;
                        while eq_pos < after_name.len() && after_name.chars().nth(eq_pos).unwrap().is_whitespace() {
                            eq_pos += 1;
                        }

                        if eq_pos < after_name.len() {
                            let ch = after_name.chars().nth(eq_pos).unwrap();
                            if ch == '=' || ch == ':' {
                                // Found the pattern, now extract the value
                                let value_start = eq_pos + 1;
                                let value_part = &after_name[value_start..];

                                // Skip leading whitespace
                                let mut val_start = 0;
                                while val_start < value_part.len() && value_part.chars().nth(val_start).unwrap().is_whitespace() {
                                    val_start += 1;
                                }

                                // Extract value based on capture pattern
                                let value = self.extract_capture_value(&value_part[val_start..]);
                                if let Some((_matched_len, captured)) = value {
                                    return Some((captured, Some(captured)));
                                }
                            }
                        }

                        search_pos = pos + name.len();
                    }
                }
            }
        }

        None
    }

    fn extract_capture_value<'a>(&self, text: &'a str) -> Option<(usize, &'a str)> {
        let p = &self.pattern;

        // Find the last (capture) group - it's after the (?:...)\s*[=:]...( pattern
        // Look for the pattern: (
        let mut paren_count = 0;
        let mut capture_start = 0;
        let mut in_capture = false;

        for (i, ch) in p.chars().enumerate() {
            if ch == '(' && !in_capture {
                paren_count += 1;
            } else if ch == ')' {
                paren_count -= 1;
            }

            // The real capture group is after the (?:...) group
            if paren_count == 0 && p[i..].starts_with('(') {
                capture_start = i;
                in_capture = true;
                break;
            }
        }

        if in_capture {
            if let Some(capture_end) = p[capture_start + 1..].find(')') {
                let capture_pat = &p[capture_start + 1..capture_start + 1 + capture_end];
                return self.match_capture_pattern(text, capture_pat);
            }
        }

        None
    }

    fn match_capture_pattern<'a>(&self, text: &'a str, pattern: &str) -> Option<(usize, &'a str)> {
        // Pattern like: [A-Za-z0-9/+=]{40}
        // or: AKIA[0-9A-Z]{16}
        // or: xo[baprs]-[0-9]{10,13}-[0-9]{10,13}-[0-9A-Za-z]{32}
        // or: AIzaSy[0-9A-Za-z_-]{33}

        if pattern.starts_with("AKIA") {
            // AWS key pattern: AKIA + 16 chars
            if text.starts_with("AKIA") && text.len() >= 20 {
                return Some((20, &text[..20]));
            }
        } else if pattern.starts_with("xo") {
            // Slack token pattern
            return self.match_slack_pattern(text);
        } else if pattern.starts_with("AIzaSy") {
            // Firebase pattern
            if text.starts_with("AIzaSy") && text.len() >= 39 {
                let capture_len = extract_length_from_pattern(pattern).unwrap_or(39);
                return Some((capture_len, &text[..capture_len]));
            }
        } else if pattern.starts_with("sk_live") {
            // Stripe pattern
            if text.starts_with("sk_live_") {
                if let Some(len) = extract_length_from_pattern(pattern) {
                    if text.len() >= len {
                        return Some((len, &text[..len]));
                    }
                }
            }
        } else if pattern.starts_with("ghp_") {
            // GitHub pattern
            if text.starts_with("ghp_") {
                if let Some(len) = extract_length_from_pattern(pattern) {
                    if text.len() >= len {
                        return Some((len, &text[..len]));
                    }
                }
            }
        } else if pattern.starts_with("npm_") {
            // NPM pattern
            if text.starts_with("npm_") {
                if let Some(len) = extract_length_from_pattern(pattern) {
                    if text.len() >= len {
                        return Some((len, &text[..len]));
                    }
                }
            }
        } else if pattern.starts_with("AC") {
            // Twilio pattern
            if text.starts_with("AC") {
                if let Some(len) = extract_length_from_pattern(pattern) {
                    if text.len() >= len {
                        return Some((len, &text[..len]));
                    }
                }
            }
        } else if pattern.starts_with('[') {
            // Character class pattern like [A-Za-z0-9/+=]{40}
            if let Some(len) = extract_length_from_pattern(pattern) {
                if text.len() >= len && self.chars_match_class(text, len, pattern) {
                    return Some((len, &text[..len]));
                }
            }
        }

        None
    }

    fn match_slack_pattern<'a>(&self, text: &'a str) -> Option<(usize, &'a str)> {
        // Slack pattern: xo[baprs]-...-...-...
        if text.len() < 50 {
            return None;
        }

        if !text.starts_with("xo") {
            return None;
        }

        let ch = text.chars().nth(2).unwrap_or(' ');
        if !"baprs".contains(ch) {
            return None;
        }

        // Parse until we get the complete slack token
        let mut pos = 3;
        let mut dash_count = 0;
        let mut segment_lengths = Vec::new();
        let mut segment_start = 3;

        while pos < text.len() && dash_count < 3 {
            let ch = text.chars().nth(pos).unwrap();
            if ch == '-' {
                segment_lengths.push(pos - segment_start);
                segment_start = pos + 1;
                dash_count += 1;
                pos += 1;
            } else if ch.is_alphanumeric() {
                pos += 1;
            } else {
                break;
            }
        }

        // Add last segment
        segment_lengths.push(pos - segment_start);

        if dash_count == 3 && segment_lengths.len() == 4 {
            if segment_lengths[0] >= 10 && segment_lengths[0] <= 13 &&
               segment_lengths[1] >= 10 && segment_lengths[1] <= 13 &&
               segment_lengths[2] >= 10 && segment_lengths[2] <= 13 &&
               segment_lengths[3] >= 32 {
                return Some((pos, &text[..pos]));
            }
        }

        None
    }

    fn chars_match_class(&self, text: &str, len: usize, pattern: &str) -> bool {
        if len > text.len() {
            return false;
        }

        for i in 0..len {
            let ch = text.chars().nth(i).unwrap();
            if pattern.contains("[A-Za-z0-9/+=]") {
                if !(ch.is_alphanumeric() || ch == '/' || ch == '+' || ch == '=') {
                    return false;
                }
            } else if pattern.contains("[0-9A-Z]") {
                if !(ch.is_ascii_digit() || ch.is_ascii_uppercase()) {
                    return false;
                }
            } else if pattern.contains("[0-9A-Za-z_-]") {
                if !(ch.is_alphanumeric() || ch == '_' || ch == '-') {
                    return false;
                }
            } else if pattern.contains("[0-9A-Za-z-]") {
                if !(ch.is_alphanumeric() || ch == '-') {
                    return false;
                }
            } else if pattern.contains("[0-9a-f]") {
                if !(ch.is_ascii_digit() || (ch >= 'a' && ch <= 'f')) {
                    return false;
                }
            } else if pattern.contains("[0-9A-Za-z]") {
                if !ch.is_alphanumeric() {
                    return false;
                }
            }
        }

        true
    }
}

fn extract_length_from_pattern(pattern: &str) -> Option<usize> {
    // Extract length from patterns like {40} or {33} or {16}
    if let Some(brace_start) = pattern.rfind('{') {
        if let Some(brace_end) = pattern.rfind('}') {
            if brace_start < brace_end {
                if let Ok(len) = pattern[brace_start + 1..brace_end].parse::<usize>() {
                    return Some(len);
                }
            }
        }
    }
    None
}

fn is_base64_char(ch: char) -> bool {
    ch.is_alphanumeric() || ch == '+' || ch == '/'
}

fn is_url_safe_char(ch: char) -> bool {
    ch.is_alphanumeric() || ch == '_' || ch == '-'
}
