// Simple pattern matcher for additional patterns
pub fn matches_simple_pattern(text: &str, pattern: &str) -> Option<&str> {
    if pattern.ends_with(".*") {
        let prefix = &pattern[..pattern.len() - 2];
        if let Some(pos) = text.find(prefix) {
            let rest = &text[pos + prefix.len()..];
            // Extract remaining part - stop at whitespace or end of line
            let mut end = 0;
            for ch in rest.chars() {
                if ch.is_whitespace() || ch == '\n' || ch == '\r' {
                    break;
                }
                end += ch.len_utf8();
            }
            let matched = &rest[..end];
            let full_match = &text[pos..pos + prefix.len() + end];
            return Some(full_match);
        }
    } else if text.contains(pattern) {
        return Some(pattern);
    }
    None
}
